    pos = sandbox.get_vehicle_position()
    x, y = pos
    vel = sandbox.get_vehicle_velocity()
    vx, vy = vel
    total_mass = sandbox.get_structure_mass()

    # Handle mud zone (x=5.5–7.5m)
    if 5.5 <= x <= 7.5:
        if vx == 0:
            # Apply forward force to start motion
            sandbox.apply_force(agent_body, (100.0, 0.0))
        else:
            time_to_trap = (9.0 - x) / vx if vx != 0 else 0
            required_speed = 2.8
            if abs(vx - required_speed) > 0.1:
                required_acceleration = (required_speed - vx) / time_to_trap
                force = required_acceleration * total_mass
                sandbox.apply_force(agent_body, (force, 0.0))

    # Handle first impulse zone (x=8.0–9.0m)
    elif 8.0 <= x <= 9.0:
        if vx == 0:
            # Apply strong forward force to meet speed trap
            sandbox.apply_force(agent_body, (500.0, 0.0))
